from dataclasses import dataclass
from typing import List, Tuple

@dataclass
class Student:
    name: str
    age: int
    score: float

class StudentRoster:
    def __init__(self):
        self._students: List[Student] = []

    def add(self, name: str, age: int, score: float) -> None:
        self._students.append(Student(name, age, score))

    def average_score(self) -> float:
        if not self._students:
            return 0.0
        return sum(student.score for student in self._students) / len(self._students)

    def top_students(self, n: int) -> List[Tuple[str, int, float]]:
        sorted_students = sorted(self._students, key=lambda s: s.score, reverse=True)
        return [(student.name, student.age, student.score) for student in sorted_students[:n]]
